css:
@page {
    size: A4;
    margin: 1cm;
}

@media print {
    .print-format {
        width: 100%;
    }

    button,
    .btn,
    input,
    select,
    textarea,
    .no-print {
        display: none !important;
    }
}

.print-format {
    font-family: Arial, sans-serif;
    font-size: 12px;
    color: #222;
}

.print-format h2 {
    margin-top: 20px;
    margin-bottom: 10px;
    font-size: 18px;
}

.print-format h3 {
    margin-bottom: 20px;
    font-size: 22px;
}

.print-format table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
}

.print-format th,
.print-format td {
    padding: 8px;
    border: 1px solid #ccc;
    text-align: left;
}

.print-format th {
    font-weight: bold;
    width: 35%;
}

.print-format h1 {
    margin-top: 25px;
    padding: 15px;
    text-align: center;
    font-size: 24px;
    font-weight: bold;
}
.credits-remaining {
    margin-top: 25px;
    padding: 15px;
    text-align: center;
    font-size: 26px;
    font-weight: bold;
    border: 2px solid #333;
}
